# Auto-generated embedded frontend bundle for Railway Python deployment
import base64
import mimetypes
from typing import Optional, Tuple

EMBEDDED_FRONTEND = {'/index.html': '', '/assets/index-DvyHXgXp.css': '', '/assets/index-C4YjGYNX.js': ''}


def get_embedded_asset(path: str) -> Optional[Tuple[bytes, str]]:
    clean_path = (path or "/").split("?")[0]
    if clean_path in ("", "/"):
        clean_path = "/index.html"
    b64_data = EMBEDDED_FRONTEND.get(clean_path)
    if b64_data is None and not clean_path.startswith("/assets/") and not clean_path.startswith("/api/") and not clean_path.startswith("/auth/"):
        clean_path = "/index.html"
        b64_data = EMBEDDED_FRONTEND.get("/index.html")
    if b64_data is None:
        return None
    raw = base64.b64decode(b64_data)
    if clean_path.endswith(".js") or clean_path.endswith(".mjs"):
        mime = "application/javascript; charset=utf-8"
    elif clean_path.endswith(".css"):
        mime = "text/css; charset=utf-8"
    elif clean_path.endswith(".html"):
        mime = "text/html; charset=utf-8"
    elif clean_path.endswith(".svg"):
        mime = "image/svg+xml"
    else:
        mime, _ = mimetypes.guess_type(clean_path)
        mime = mime or "application/octet-stream"
    return raw, mime
